shots.draw_js:
clearScene();
setEq("$$\\pi'(s)=\\arg\\max_a\\Big[R(s,a)+\\gamma\\sum_{s'}P(s'\\mid s,a)V(s')\\Big]$$","top");
note("这一步要 P 和 R",640,300,"r lg");
setCap("L2 里从 <b>V</b> 贪心是理所当然的。但它要穿过一次 Bellman 回溯 —— <b>而模型已经没有了</b>。");

clearScene();setEq(null);
setBig("估 V 就够了","反正贪心一下就能得到策略");
setCap("这个直觉在 L2 <b>完全成立</b> —— 那时 P 和 R 都在手上。");

clearScene();
setEq("$$\\pi'(s)=\\arg\\max_a Q(s,a)$$","top");
note("只要一张表",640,300,"g lg");
setCap("换成 <b>Q</b>：贪心改进变成一次查表取最大，<b>模型整个消失了</b>。");

clearScene();
setEq("$$Q^{\\pi}(s,a)=\\mathbb{E}_{\\pi}\\big[G_t \\mid s_t=s,\\ a_t=a\\big]$$","top");
backup({x:640,y:250,dy:90,r:18,spread:200,levels:["s","a","s"],branch:[2,2],hl:[1],
  labels:["s","a 由你指定","之后按 π"]});
setCap("Q 比 V 多记一件事：<b>第一步的动作由你指定</b>，从第二步起才交给 π。");

clearScene();setEq(null);
fillBars({order:[0,1],step:700,vals:[7,14],x:400,y:420,w:480,h:160,max:16,
  label:function(i){return ["V 表 |S|","Q 表 |S||A|"][i];},
  cls:function(i){return i===0?"b":"g";},
  fmt:function(v){return v.toFixed(0);}});
note("多存 7 个数",640,466,"y");
setCap("代价只是把表撑大 |A| 倍。火星车上：<b>7 个数变 14 个数，换掉整个模型</b>。");

clearScene();setEq(null);
lamps({y:280,gap:330,items:[
  {label:"从 V 贪心",sub:"要 P 和 R",state:"dead"},
  {label:"从 Q 贪心",sub:"只要查表",state:"on"},
  {label:"代价",sub:"表大 |A| 倍",state:"on"}]});
note("无模型控制的第一次换位",640,420,"y");
setCap("<b>指名反驳</b>：V 不是精度不够，是<b>贪心那一步本身需要模型</b>。");

clearScene();setEq(null);
gridworld({rows:1,cols:7,cs:110,y:250,
  tag:function(i,j){return "s"+(j+1);},
  pol:function(){return "r";},
  cls:function(){return "b";}});
note("每格只试过一个动作",640,420,"r");
setCap("确定性贪心策略跑一万个回合，<b>向左那个动作一次都没被试过</b>。");

clearScene();setEq(null);
setBig("按当前最优走","反正 Q 会慢慢收敛到对的");
setCap("这句话在<b>有模型</b>的策略迭代里是对的 —— L2 的策略迭代正是这么做的。");

clearScene();
setEq("$$Q(s,a)\\;\\leftarrow\\;Q(s,a)+\\alpha\\big[\\,\\text{target}-Q(s,a)\\,\\big]$$","top");
note("没采到就不更新",640,300,"r lg");
setCap("更新只发生在<b>被采样到的</b> (s,a) 上。没走过的动作，Q 永远停在初值。");

clearScene();setEq(null);
bars({vals:[7,7],x:400,y:420,w:480,h:160,max:8,
  label:function(i){return ["被更新过","从未被更新"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(0);}});
note("一半的表是盲区",640,466,"y");
setCap("Q 表 14 个格子，确定性贪心只会碰到 <b>7 个</b>。另外 7 个是盲区。");

clearScene();setEq(null);
lamps({y:280,gap:300,items:[
  {label:"确定性贪心",sub:"每状态只采一个动作",state:"dead"},
  {label:"于是",sub:"另一半 Q 停在初值",state:"dead"},
  {label:"而贪心基于 Q",sub:"坏初值自我锁死",state:"dead"}]});
note("探索不是工程细节",640,420,"r");
setCap("<b>指名反驳</b>：不是收敛慢，是<b>那半张表根本没有数据</b>。");

clearScene();setEq(null);
note("以 ε 概率随机",420,260,"y lg");
note("否则贪心",860,260,"g lg");
setCap("ε-greedy 的定义只有一句话。<b>问题在「随机」那一支到底包不包括贪心动作。</b>");

clearScene();setEq(null);
setBig("P(贪心) = 1 − ε","幻灯片和口述里好几处就是这么写的");
setCap("这个写法在讲座里出现了不止一次 —— 而且<b>它把概率加不到 1</b>。");

clearScene();
setEq("$$\\pi(a^*\\mid s)=(1-\\varepsilon)+\\frac{\\varepsilon}{|A|}$$","top");
note("随机支也可能抽中它",640,320,"y lg");
setCap("随机分支是<b>在所有动作里</b>均匀抽，贪心动作也在里面 —— 那一份要加回去。");

clearScene();setEq(null);
fillBars({order:[0,1],step:700,vals:[0.900,0.950],x:400,y:400,w:480,h:150,max:1,
  label:function(i){return ["1−ε（错）","1−ε+ε/|A|（对）"][i];},
  cls:function(i){return i===0?"r":"g";},
  fmt:function(v){return v.toFixed(3);}});
note("ε=0.1，|A|=2",640,446,"sm");
setCap("ε=0.1、|A|=2：真实的贪心概率是 <b>0.950</b>，不是 0.900。");

clearScene();setEq(null);
fillBars({order:[0,1],step:700,vals:[0.500,0.750],x:400,y:400,w:480,h:150,max:1,
  label:function(i){return ["1−ε（错）","1−ε+ε/|A|（对）"][i];},
  cls:function(i){return i===0?"r":"g";},
  fmt:function(v){return v.toFixed(3);}});
note("ε=0.5，|A|=2",640,446,"sm");
setCap("ε=0.5 时差得离谱：真实值 <b>0.750</b>，错写成 0.500 —— <b>相对误差 50%</b>。");

clearScene();setEq(null);
note("1−ε",360,280,"r lg");
note("1−ε+ε/|A|",920,280,"g lg");
note("差的是 ε/|A| 那一份",640,400,"y lg");
setCap("<b>指名反驳</b>：随机分支包含贪心动作。两个学生先后提出，才被说清楚。");
